"""Migration of the Meridian CRM 4.2 case escalation nightly job."""

from datetime import date


def _datediff(today: str, open_date: object) -> int:
    """Return whole calendar days today - open_date under legacy semantics."""
    if not today or today == "00000000" or not open_date or open_date == "00000000":
        return 0

    open_date_text = str(open_date)
    if not open_date_text or open_date_text == "00000000":
        return 0

    current = date(int(today[0:4]), int(today[4:6]), int(today[6:8]))
    opened = date(
        int(open_date_text[0:4]),
        int(open_date_text[4:6]),
        int(open_date_text[6:8]),
    )
    return (current - opened).days


def escalate(cases: list[dict], today: str) -> list[dict]:
    """Return workflow events for overdue live support cases."""
    events: list[dict] = []

    for case in sorted(cases, key=lambda row: row.get("CASE_ID", "")):
        if case.get("DEL_FLG", "") == "Y":
            continue

        status = case.get("STAT_CD", "")
        age_days = _datediff(today, case.get("OPEN_DT", ""))

        if status == "N" and age_days >= 2:
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case.get("CASE_ID", "")),
                    "event": "auto_escalate",
                }
            )
        elif status == "A" and case.get("ESC_FLG", "") != "Y" and age_days >= 7:
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case.get("CASE_ID", "")),
                    "event": "auto_escalate",
                }
            )

    return events
